import os, json
import re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()

# New hypothesis: a cell becomes 2 if it equals the most common value AND has TWO DISTINCT different values as neighbors
def predict(grid):
    h, w = len(grid), len(grid[0])

    # Find the dominant "background" color (most frequent)
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    bg = max(counts, key=counts.get)

    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and c > 0 and c < w-1:
                if grid[r][c-1] != bg and grid[r][c+1] != bg:
                    result[r][c] = 2
    return result

# Verify with demo 1
demo1_in = G['Demo pair 1 input']
demo1_out = G['Demo pair 1 output']
pred1 = predict(demo1_in)
print("Demo 1 prediction matches:", pred1 == demo1_out)
if not (pred1 == demo1_out):
    print("\nDifferences in Demo 1:")
    for r in range(len(pred1)):
        for c in range(len(pred1[0])):
            if pred1[r][c] != demo1_out[r][c]:
                print(f"  ({r},{c}): got {pred1[r][c]}, expected {demo1_out[r][c]}")

# Verify with demo 2  
demo2_in = G['Demo pair 2 input']
demo2_out = G['Demo pair 2 output']
pred2 = predict(demo2_in)
print("\nDemo 2 prediction matches:", pred2 == demo2_out)
if not (pred2 == demo2_out):
    print("\nDifferences in Demo 2:")
    for r in range(len(pred2)):
        for c in range(len(pred2[0])):
            if pred2[r][c] != demo2_out[r][c]:
                print(f"  ({r},{c}): got {pred2[r][c]}, expected {demo2_out[r][c]}")

# Apply to test input
test_in = G['Test input']
test_pred = predict(test_in)

print("\nTest prediction shape:", len(test_pred), "x", len(test_pred[0]))
